import 'package:flutter/material.dart';
class PageWrap extends StatelessWidget{const PageWrap({super.key,required this.child,this.maxWidth=1100});final Widget child;final double maxWidth;@override Widget build(BuildContext context)=>SafeArea(child:Center(child:ConstrainedBox(constraints:BoxConstraints(maxWidth:maxWidth),child:child)));}
class SectionTitle extends StatelessWidget{const SectionTitle(this.title,{super.key,this.action});final String title;final Widget? action;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.fromLTRB(4,22,4,10),child:Row(children:[Expanded(child:Text(title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700))),?action]));}
class EmptyHint extends StatelessWidget{const EmptyHint(this.text,{super.key});final String text;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(24),child:Center(child:Text(text,style:TextStyle(color:Theme.of(context).colorScheme.onSurfaceVariant))));}
